/* Glossary: definitions for every term the dashboard uses.
   Each entry: id, term, cat (category id), short (one or two sentences, shown in the hover popover),
   long (optional extra HTML for the Glossary page), aka (labels that should show this definition;
   strings match whole labels case-insensitively, "/regex/" strings are regular expressions),
   see (related entry ids). */
(function () {
  "use strict";
  const BL = (window.BL = window.BL || {});

  BL.GLOSSARY_CATS = [
    { id: "model", label: "Models & architecture" },
    { id: "quant", label: "File formats & quantization" },
    { id: "engine", label: "Engines & runtime settings" },
    { id: "speed", label: "Speed metrics" },
    { id: "memory", label: "Memory" },
    { id: "tests", label: "This tool's tests & settings" },
    { id: "thinking", label: "Thinking (reasoning) modes" },
    { id: "public", label: "Public benchmark data" },
    { id: "bench", label: "Benchmarks (named tests)" },
    { id: "dashboard", label: "Dashboard" },
  ];

  BL.GLOSSARY = [
    // ------------------------------------------------------------- models & architecture
    { id: "llm", term: "LLM (large language model)", cat: "model",
      short: "A neural network trained on huge amounts of text to predict the next token. Chat assistants, coding agents and tools like Hermes or n8n AI nodes all run on one.",
      see: ["token", "parameters"] },
    { id: "token", term: "Token", cat: "model", aka: ["tokens", "tok"],
      short: "The unit a model reads and writes: a word or a piece of a word. In English, one token is roughly ¾ of a word (about 4 characters). All speeds here are in tokens per second.",
      long: "Different models split text differently (their <b>tokenizer</b>), so the same document can be 73k tokens for one model and 83k for another. The tool records the count each model actually reports.",
      see: ["tokenizer", "tps"] },
    { id: "tokenizer", term: "Tokenizer", cat: "model",
      short: "The part of a model that cuts text into tokens. Models with large vocabularies (Gemma: 262k entries) need fewer tokens for the same text.",
      see: ["token"] },
    { id: "parameters", term: "Parameters (B)", cat: "model", aka: ["params", "parameters", "params_total_b", "/^\\d+(\\.\\d+)?b$/"],
      short: "The learned numbers (weights) inside a model, counted in billions (B). More parameters usually means more knowledge and ability, but also more memory and slower speed.",
      long: "Rough memory rule: parameters × bits per weight ÷ 8. A 26B model at 4 bits ≈ 13 GB, plus the vision encoder, KV cache and engine overhead.",
      see: ["dense", "moe", "quantization"] },
    { id: "dense", term: "Dense model", cat: "model", aka: ["dense"],
      short: "Every parameter is used for every token. Speed scales with the full model size, e.g. Gemma 4 31B reads all 31B weights for each generated token.",
      see: ["moe"] },
    { id: "moe", term: "MoE (Mixture of Experts)", cat: "model", aka: ["moe", "mixture of experts", "experts", "num_experts"],
      short: "The model is split into many small 'experts', and a router picks only a few for each token. You need memory for all of them, but each token only uses the active ones, so it generates much faster than a dense model of the same size.",
      long: "Gemma 4 26B A4B has 128 experts; 8 (plus 1 shared) are active per token, i.e. 3.8B of 25.2B parameters. That's why it decodes ~5× faster than the dense 27–31B models in your results while needing a similar amount of memory.",
      see: ["active-params", "dense", "decode"] },
    { id: "active-params", term: "Active parameters (e.g. A4B, A3B)", cat: "model", aka: ["a4b", "a3b", "active", "/^a\\d+b$/", "params_active_b"],
      short: "In a model name, 'A4B' means about 4 billion parameters are Active per token (MoE). '26B A4B' = 26B total, ~4B used per token. Speed follows the active count; memory follows the total.",
      see: ["moe", "parameters"] },
    { id: "instruct", term: "Instruct / IT / Chat model", cat: "model", aka: ["it", "instruct", "chat", "thinking version"],
      short: "A model trained to follow instructions, chat and call tools ('-it', '-Instruct' or '-Chat' in the name). The 'Base' model only continues text; 'Thinking' versions are instruct models trained to reason before answering. You want instruct (or thinking) models for assistants and agents.",
      see: ["base-model"] },
    { id: "base-model", term: "Base model", cat: "model", aka: ["base model", "base"],
      short: "The original, unquantized model a file was made from (e.g. google/gemma-4-31B-it). Public scores usually describe the base model, not your 4-bit copy.",
      see: ["applies-to", "quantization"] },
    { id: "context-window", term: "Context window / context length", cat: "model", aka: ["context", "context length", "max context", "context window", "max_context_length", "context_length", "num_ctx"],
      short: "How many tokens the model can see at once: your prompt, the conversation so far, documents and its own answer. The model's maximum (e.g. 256k) and what the engine is set to load (here 112k) can differ.",
      long: "A bigger loaded context needs more memory (KV cache) but lets you paste longer documents. This tool loads every model at 114,688 tokens (112k) so the ~73–85k-token document fits with room for thinking.",
      see: ["kv-cache", "long-test"] },
    { id: "vision", term: "Vision (multimodal)", cat: "model", aka: ["vision", "modalities"],
      short: "The model can take images as input (screenshots, charts, photos) as well as text. Usually needs an extra 'projector' / vision encoder file.",
      see: ["mmproj"] },
    { id: "tool-use", term: "Tool use / function calling", cat: "model", aka: ["tool use", "tools", "trained_for_tool_use", "tool_use"],
      short: "The model was trained to output structured calls to tools/APIs (e.g. 'search_web', an n8n node, an MCP server). Essential for agents like Hermes.",
      see: ["bfcl", "tau2", "mcp-atlas"] },
    { id: "reasoning-model", term: "Thinking / reasoning model", cat: "model", aka: ["think", "reasoning", "thinking"],
      short: "A model that can write a hidden chain of thought before its visible answer. It usually answers hard questions better, but spends extra tokens and time first.",
      see: ["thinking-off", "thinking-high", "first-visible"] },
    { id: "embedding-model", term: "Embedding model", cat: "model", aka: ["embedding"],
      short: "A small model that turns text into vectors for search/RAG (e.g. nomic-embed-text). It doesn't chat; the tool unloads it during benchmarks and reloads it afterwards.",
      see: ["clean-machine"] },
    { id: "mtp", term: "MTP / speculative decoding / drafter", cat: "model", aka: ["mtp", "drafter", "speculative decoding"],
      short: "A trick to speed up generation: a tiny 'draft' model (or extra prediction heads) guesses several tokens ahead and the big model checks them in one go. Same output, faster decode when guesses are right.",
      see: ["decode"] },

    // ------------------------------------------------------------- formats & quantization
    { id: "quantization", term: "Quantization", cat: "quant", aka: ["quant", "quantization", "bits", "bits per weight"],
      short: "Storing a model's weights with fewer bits (e.g. 4 instead of 16) to make it smaller and faster. It costs a little quality; 8-bit is near-lossless, 4-bit is the usual sweet spot, below 4 degrades faster.",
      long: "Original models are usually 16-bit (BF16). A 4-bit copy is ~4× smaller. Because decoding speed is limited by how many bytes are read per token, smaller files also generate faster.",
      see: ["qat", "q4_0", "q4_k_m", "mlx-quant", "bf16"] },
    { id: "qat", term: "QAT (Quantization-Aware Training)", cat: "quant", aka: ["qat"],
      short: "The model maker trained the model while simulating 4-bit precision, so the 4-bit version keeps almost all of the full model's quality. Usually better than an ordinary 4-bit conversion of the same model.",
      see: ["quantization", "q4_0"] },
    { id: "file-format", term: "Format (GGUF / MLX)", cat: "quant", aka: ["format", "file format"],
      short: "How the model file is packaged, which decides which engine runs it: GGUF runs on llama.cpp (Ollama, LM Studio, any OS); MLX runs on Apple's MLX engine (Macs only, often faster there).",
      see: ["gguf", "mlx", "engine"] },
    { id: "model-size", term: "Size (on disk)", cat: "quant", aka: ["size", "file size", "size_bytes"],
      short: "How big the downloaded model is. It's also roughly the RAM needed just to hold the weights; add the KV cache and engine overhead for real use (see Loaded and Peak memory).",
      see: ["quantization", "mem-loaded", "mem-peak"] },
    { id: "gguf", term: "GGUF", cat: "quant", aka: ["gguf"],
      short: "The single-file model format of the llama.cpp project, used by Ollama and LM Studio's llama.cpp engine. Runs on Mac, Windows and Linux, on CPU and GPU.",
      long: "A .gguf file contains the weights, the tokenizer and metadata. Quantization levels have names like Q4_0, Q4_K_M or Q8_0. Vision models need a separate 'mmproj' file.",
      see: ["llama-cpp", "mlx", "q4_k_m"] },
    { id: "mlx", term: "MLX", cat: "quant", aka: ["mlx"],
      short: "Apple's machine-learning framework for Apple Silicon. 'MLX' models are folders of safetensors files quantized for it. On a Mac, MLX models are often the fastest option in LM Studio.",
      long: "MLX models only run on Apple Silicon Macs. LM Studio runs them with its MLX engine; Ollama has its own MLX runner, which expects a different internal layout, so an LM Studio MLX folder can't simply be imported into Ollama.",
      see: ["gguf", "mlx-engine", "safetensors", "mlx-quant"] },
    { id: "safetensors", term: "safetensors", cat: "quant", aka: ["safetensors"],
      short: "Hugging Face's standard file format for model weights (safe to load, no code inside). MLX models and original full-precision models are distributed as safetensors.",
      see: ["mlx", "huggingface"] },
    { id: "q4_0", term: "Q4_0", cat: "quant", aka: ["q4_0"],
      short: "A simple llama.cpp 4-bit format: every block of 32 weights shares one scale. Fast and compact. Google's QAT releases use it because the model was trained for exactly this format.",
      see: ["qat", "q4_k_m"] },
    { id: "q4_k_m", term: "Q4_K_M (and other K-quants)", cat: "quant", aka: ["q4_k_m", "q4_k_s", "q5_k_m", "q6_k", "q3_k_m", "k-quant", "/^q\\d_k(_[sml])?$/"],
      short: "llama.cpp 'K-quant' formats mix precisions inside super-blocks to keep more quality at the same size. The number is the main bit width; S/M/L = small/medium/large. Q4_K_M is the most popular default.",
      see: ["q4_0", "q8_0", "quantization"] },
    { id: "q8_0", term: "Q8_0", cat: "quant", aka: ["q8_0", "8bit", "8-bit"],
      short: "8-bit quantization: near-lossless quality, about twice the size of 4-bit and slower to generate.",
      see: ["quantization"] },
    { id: "mlx-quant", term: "MLX 4-bit / 6-bit / 8-bit", cat: "quant", aka: ["4bit", "5bit", "6bit", "/^\\d+-?bit$/", "group size", "affine"],
      short: "MLX quantization: weights are stored with N bits in groups (usually 64 weights) that share a scale and offset. Some layers (e.g. the MoE router) are often kept at 8 bits for quality.",
      see: ["mlx", "quantization"] },
    { id: "mxfp4", term: "MXFP4 / NVFP4 / MXFP8", cat: "quant", aka: ["mxfp4", "nvfp4", "mxfp8"],
      short: "4- or 8-bit floating-point formats with a shared scale per small block ('microscaling'). gpt-oss was trained and released natively in MXFP4.",
      see: ["quantization"] },
    { id: "bf16", term: "BF16 / FP16 (full precision)", cat: "quant", aka: ["bf16", "fp16", "f16", "full precision"],
      short: "16-bit numbers: how most models are originally released. Best quality, ~4× the size of a 4-bit file and much slower to run locally.",
      see: ["quantization"] },
    { id: "splash", term: "Splash (engine) / yuzu format", cat: "engine", aka: ["splash", "yuzu", "dflash", "dflash 2"],
      short: "An inference engine for Apple Silicon from Inco AI, available in LM Studio as an experimental engine. It runs its own packed model format (LM Studio lists it as 'yuzu') and speeds up writing with DFlash 2 speculative decoding, for a few supported models (Qwen3.8-27B, Qwen3.6-35B-A3B).",
      see: ["mtp", "engine", "mlx-engine"] },
    { id: "quant-recipes", term: "i-quants, imatrix, UD (quantization recipes)", cat: "quant", aka: ["iq4_xs", "iq3_xxs", "iq2_m", "iq1_s", "imatrix", "ud", "unsloth dynamic", "dwq", "optiq", "/^iq\\d/", "/^ud-/"],
      short: "Smarter ways to choose how many bits each part of the model gets. i-quants (IQ4_XS, IQ3…) use an importance matrix (imatrix) measured on sample text to keep the most important weights precise; UD (Unsloth Dynamic) picks the precision layer by layer. Community recipes like DWQ or OptiQ do similar things for MLX. Same model, better quality for the size.",
      see: ["quantization", "q4_k_m"] },
    { id: "community-converters", term: "Converters (lmstudio-community, mlx-community, unsloth…)", cat: "quant", aka: ["lmstudio-community", "mlx-community", "unsloth", "bartowski", "ggml-org", "converters", "converter"],
      short: "Groups that take a model maker's original weights and republish them as GGUF or MLX at different bit levels. The model is the same; only the packaging differs. lmstudio-community files are the ones LM Studio's catalogue shows by default.",
      see: ["huggingface", "derived-model"] },
    { id: "derived-model", term: "Derived models (fine-tunes, abliterated, distills, merges)", cat: "model", aka: ["fine-tune", "finetune", "abliterated", "uncensored", "heretic", "distill", "distilled", "merge", "derived"],
      short: "Models changed by someone else after release: fine-tuned on new data, 'abliterated'/'uncensored' (safety refusals removed), 'Distill' (a smaller model trained to imitate a bigger one), or merged from several models. They behave differently from the original, and its public benchmark scores don't apply.",
      see: ["base-model", "community-converters"] },
    { id: "mmproj", term: "mmproj / projector / vision encoder", cat: "quant", aka: ["mmproj", "projector", "vision encoder", "clip"],
      short: "The extra component (often a separate file) that turns an image into tokens the language model can read. Only needed for image input.",
      see: ["vision"] },
    { id: "variant", term: "Variant", cat: "quant", aka: ["variant", "selected_variant"],
      short: "LM Studio groups several downloads of the same model (e.g. MLX 4-bit and GGUF Q4_0) under one name as 'variants'. Ollama calls them tags (e.g. gemma4:26b-a4b-it-qat).",
      see: ["model-uid"] },
    { id: "huggingface", term: "Hugging Face", cat: "quant", aka: ["hugging face", "hf repo", "huggingface"],
      short: "The main website where models are published (huggingface.co). Model makers post the original weights and a model card; community groups (lmstudio-community, mlx-community, unsloth…) post converted copies.",
      see: ["model-card", "base-model"] },
    { id: "model-card", term: "Model card", cat: "quant", aka: ["model card"],
      short: "The README page of a model on Hugging Face: description, license, intended use and usually a table of benchmark scores. The tool reads these tables automatically.",
      see: ["card-table"] },
    { id: "license", term: "License", cat: "quant", aka: ["license"],
      short: "The terms you may use the model under (e.g. Apache-2.0, Gemma license). Matters if you use a model commercially.",
      see: [] },

    // ------------------------------------------------------------- engines & runtime
    { id: "engine", term: "Engine (inference engine)", cat: "engine", aka: ["engine", "engines", "runtime"],
      short: "The app that actually runs the model and serves it over an API. Here: LM Studio and Ollama. The same model file can run at different speeds in different engines.",
      see: ["lmstudio", "ollama", "llama-cpp", "mlx-engine"] },
    { id: "lmstudio", term: "LM Studio", cat: "engine", aka: ["lm studio", "lmstudio"],
      short: "A desktop app to download and run local models, with two engines (llama.cpp for GGUF, MLX for MLX models) and a local API server (port 1234).",
      see: ["engine", "ollama"] },
    { id: "ollama", term: "Ollama", cat: "engine", aka: ["ollama"],
      short: "A lightweight local model runner with a command line and an API (port 11434). Models are pulled by tag (e.g. gpt-oss:20b). Runs GGUF via llama.cpp and some models via its MLX runner.",
      see: ["engine", "lmstudio"] },
    { id: "llama-cpp", term: "llama.cpp", cat: "engine", aka: ["llama.cpp", "llama-server"],
      short: "The open-source C/C++ inference engine behind GGUF. Both Ollama and LM Studio use it for GGUF files (in different versions and with different settings).",
      see: ["gguf"] },
    { id: "mlx-engine", term: "MLX engine", cat: "engine", aka: ["mlx-engine", "mlx engine", "mlx runner"],
      short: "The engine that runs MLX models on Apple Silicon (LM Studio's mlx-engine, or Ollama's MLX runner).",
      see: ["mlx"] },
    { id: "apple-silicon", term: "Apple Silicon / unified memory", cat: "engine", aka: ["unified memory", "apple silicon", "chip", "gpu cores", "cpu / gpu cores"],
      short: "Macs with M-series chips share one pool of memory between CPU and GPU. A model can use most of your RAM as 'GPU memory', which is why a 64 GB Mac can run 30B-class models.",
      see: ["memory-bandwidth", "wired"] },
    { id: "memory-bandwidth", term: "Memory bandwidth", cat: "engine", aka: ["bandwidth", "memory bandwidth", "memory_bandwidth_gbps"],
      short: "How many GB per second the chip can read from memory. Generating each token reads all active weights once, so decode speed is roughly bandwidth ÷ size of the active weights.",
      see: ["decode", "moe"] },
    { id: "api", term: "API / API token", cat: "engine", aka: ["base url", "api", "api token"],
      short: "Engines expose a local web API (OpenAI-compatible or native) that tools like Hermes, n8n and this benchmark use. LM Studio can require an API token for it.",
      see: [] },
    { id: "load", term: "Load / unload", cat: "engine", aka: ["load", "unload"],
      short: "Loading copies the model from disk into memory so it can answer; unloading frees that memory. Only loaded models use RAM. Engines can also auto-load a model on the first request (JIT).",
      see: ["cold-load", "clean-machine"] },
    { id: "flash-attention", term: "Flash attention", cat: "engine", aka: ["flash attention", "flash_attention"],
      short: "A faster, more memory-efficient way to compute attention, especially for long contexts. The tool keeps each engine's default and records it.",
      see: ["kv-cache"] },
    { id: "kv-cache", term: "KV cache", cat: "engine", aka: ["kv cache", "kv cache on gpu", "offload_kv_cache_to_gpu", "kv"],
      short: "The model's working memory for the current conversation: for every token in context it stores attention 'keys' and 'values'. It grows with context length, which is why memory rises after the 64k document.",
      see: ["context-window", "mem-kv", "prompt-cache"] },
    { id: "prompt-cache", term: "Prompt cache (prefix cache)", cat: "engine", aka: ["prompt cache", "prefix cache", "cache"],
      short: "If a new request starts with exactly the same text as the last one (same system prompt, same conversation), the engine reuses the KV cache and only processes the new part. That's why follow-up questions about the long document answer in ~1 s instead of minutes.",
      see: ["cache-hit", "followup-ttft", "session-tag"] },
    { id: "eval-batch", term: "Eval batch size", cat: "engine", aka: ["eval batch size", "eval_batch_size", "batch"],
      short: "How many prompt tokens llama.cpp processes in one step. Larger batches can speed up prefill at the cost of memory. Engine default is kept.",
      see: ["prefill"] },
    { id: "parallel", term: "Parallel (slots)", cat: "engine", aka: ["parallel"],
      short: "How many requests LM Studio can serve at the same time from one loaded model. The benchmark sends one request at a time.",
      see: [] },
    { id: "keep-alive", term: "keep_alive / JIT loading / TTL", cat: "engine", aka: ["keep_alive", "ttl", "jit"],
      short: "Settings that decide how long an engine keeps a model loaded after use, and whether it loads models automatically when an app asks for them. Can make a model reappear in memory during a benchmark (the watchdog catches that).",
      see: ["contamination"] },

    // ------------------------------------------------------------- speed metrics
    { id: "tps", term: "tok/s (tokens per second)", cat: "speed", aka: ["tok/s", "tokens per second", "tps"],
      short: "Throughput: how many tokens are processed or generated per second. Reading speed (prefill) and writing speed (decode) are very different and are reported separately.",
      see: ["prefill", "decode"] },
    { id: "ttft", term: "TTFT (time to first token)", cat: "speed", aka: ["ttft", "ttft s", "short ttft", "64k ttft", "time to first token", "first token", "ttft_s"],
      short: "Seconds from sending a request until the first token comes back. For short prompts it's mostly overhead (<1 s); for long prompts it's dominated by prefill: roughly prompt tokens ÷ prefill speed.",
      long: "Example from your data: a 73k-token document at 178 tok/s prefill ≈ 410 s before the first word. With thinking on, the first token is a thinking token; see 'first visible token' for when the answer starts.",
      see: ["prefill", "first-visible", "cold-ttft", "warm-ttft"] },
    { id: "first-visible", term: "First visible token", cat: "speed", aka: ["1st visible", "first visible", "first_visible_s", "high · first visible token", "first visible token"],
      short: "Seconds until the first token of the actual answer (after any hidden thinking). With thinking off it equals TTFT; with thinking High it's what the user really waits for.",
      see: ["ttft", "thinking-high"] },
    { id: "prefill", term: "Prefill (prompt processing)", cat: "speed", aka: ["prefill", "64k prefill", "prompt processing", "prefill_tps", "prompt tok"],
      short: "Reading the input: the model processes your whole prompt (system prompt, history, documents) before it can answer. Measured in tokens/s. Determines how long you wait with big documents.",
      long: "Prefill is compute-bound and processes many tokens in parallel, so it's much faster than decode (hundreds to thousands of tok/s). Matters most for RAG, long documents and agents with big tool definitions.",
      see: ["ttft", "decode", "long-test"] },
    { id: "decode", term: "Decode (generation speed)", cat: "speed", aka: ["decode", "short decode", "generation", "decode_tps", "decode speed"],
      short: "Writing the answer, one token at a time, in tokens/s. Determines how long a reply takes once it has started: a 500-token answer at 15 tok/s takes ~33 s; at 80 tok/s ~6 s.",
      long: "Decode is limited by memory bandwidth (all active weights are read for every token), so it drops as the context fills up and is much higher for MoE models.",
      see: ["prefill", "memory-bandwidth", "moe"] },
    { id: "total-time", term: "Total time", cat: "speed", aka: ["total", "total s", "total_s", "wall"],
      short: "Full time of a request or conversation, from sending to the last token: ≈ TTFT + output tokens ÷ decode speed.",
      see: ["ttft", "decode"] },
    { id: "cold-load", term: "Cold load / reload", cat: "speed", aka: ["load time", "cold load", "warm load", "reload", "cold_load_s", "warm_load_s", "cold vs. warm"],
      short: "Seconds to load the model into memory. 'Cold' = first load; the second load is often faster because macOS still has the file in its disk cache. Matters if your engine loads models on demand.",
      see: ["cold-ttft", "load"] },
    { id: "cold-ttft", term: "Cold first token", cat: "speed", aka: ["cold first token", "cold_first_ttft_s", "first token after load"],
      short: "Time to first token for the very first request after loading. Often slower than later requests because the GPU still has to warm up (compile kernels, page in weights).",
      see: ["warm-ttft", "cold-load"] },
    { id: "warm-ttft", term: "Warm TTFT", cat: "speed", aka: ["warm ttft", "warm first token", "warm_ttft_s"],
      short: "Time to first token for a short prompt once the model is loaded and warmed up: the best-case responsiveness you'll feel in chat.",
      see: ["cold-ttft", "ttft"] },
    { id: "cache-hit", term: "Cache-hit TTFT", cat: "speed", aka: ["cache-hit ttft", "cache hit", "cache_hit_ttft_s", "off cache-hit ttft"],
      short: "Time to first token when the exact same prompt is sent again, so the engine can reuse its prompt cache. Shows how much the cache saves (e.g. minutes → ~1 s for the 64k document). Measured with reasoning off (or at the lowest level, for models like gpt-oss that can't turn it off).",
      see: ["prompt-cache"] },
    { id: "followup-ttft", term: "Follow-up TTFT", cat: "speed", aka: ["follow-up ttft", "followup", "long_off_followup_ttft_s"],
      short: "Time to first token for the follow-up questions after the long document was loaded. Thanks to the prompt cache only the new question is processed, so this is fast if the engine caches well.",
      see: ["prompt-cache", "long-test"] },
    { id: "median", term: "Median / min / max", cat: "speed", aka: ["median", "min", "max", "median of repeats"],
      short: "Each measurement is repeated 3 times; the median (middle value) is shown because it ignores one-off hiccups. Min/max show how stable the result was.",
      see: ["repeats"] },

    // ------------------------------------------------------------- memory
    { id: "mem-engine", term: "Engine memory (footprint)", cat: "memory", aka: ["memory gb", "engine memory", "engine footprint", "footprint", "phys_footprint", "memory snapshots", "engine_bytes", "memory"],
      short: "Memory used by the engine's processes (LM Studio or Ollama), as reported by the operating system. This is what the model really costs you in RAM.",
      long: "On macOS the tool takes, for each engine process, the larger of 'phys_footprint' (includes GPU/Metal allocations, used by MLX) and 'RSS' (includes model files mapped from disk, used by llama.cpp/GGUF). Without both, one engine or the other would be under-counted.",
      see: ["rss", "mem-loaded", "mem-peak"] },
    { id: "rss", term: "RSS (resident set size)", cat: "memory", aka: ["rss", "process-rss", "max(footprint,rss)"],
      short: "The part of a process's memory currently in physical RAM, including files mapped into memory. llama.cpp maps GGUF files this way, so RSS captures their weights.",
      see: ["mem-engine"] },
    { id: "mem-idle", term: "Idle memory", cat: "memory", aka: ["idle", "mem_idle_gb"],
      short: "Engine memory before the model is loaded: the app's own overhead.",
      see: ["mem-loaded"] },
    { id: "mem-loaded", term: "Loaded memory (empty context)", cat: "memory", aka: ["loaded", "loaded_empty", "mem_loaded_gb", "loaded memory"],
      short: "Engine memory right after loading, before any conversation: roughly the model weights plus the engine. The minimum RAM this model needs.",
      see: ["mem-peak", "mem-kv"] },
    { id: "mem-kv", term: "Memory after the long document", cat: "memory", aka: ["after_long_prompt", "after long prompt", "mem_long_gb", "mem_kv_long_gb"],
      short: "Engine memory after the ~73–85k-token document was read. The difference with 'loaded' is mostly KV cache, the price of a long context.",
      see: ["kv-cache", "mem-peak"] },
    { id: "mem-peak", term: "Peak memory", cat: "memory", aka: ["peak", "peak memory", "mem_peak_gb", "peak gb"],
      short: "Highest engine memory seen during the whole run (long document + thinking). Plan for this number: keep it comfortably below your RAM (leave at least 8 GB for the operating system and other apps: on a 64 GB computer, a peak up to ~56 GB) so nothing starts swapping. The table colours it amber above 75% of RAM and red when less than 8 GB would be left.",
      see: ["swap", "mem-loaded"] },
    { id: "ctx-peak", term: "Context at peak (Ctx @ peak)", cat: "memory", aka: ["ctx @ peak", "context at peak", "peak_context_tokens"],
      short: "How many tokens were in the model's context at the moment its memory peaked. For most models that's while reading the ~73–80k-token test document: the peak comes from a temporary working-memory spike during reading, not just from the stored context.",
      see: ["safe-context", "reading-spike", "mem-peak"] },
    { id: "safe-context", term: "Safe context (suggested max context)", cat: "memory", aka: ["safe ctx", "safe context", "safe context (ram − 8 gb)", "safe context (75% ram)", "suggested max context"],
      short: "Estimated largest context window that keeps this model's peak memory below the computer's RAM minus 8 GB (left for the operating system and apps), from its own run; the tooltip also shows 60%, 75% and 85% of RAM. Use it as a starting point for the context length you set in LM Studio, Ollama or Hermes. Values beyond the tested ~75k tokens are extrapolations.",
      long: "Memory above 'loaded' (the context cache plus the reading spike) is scaled linearly with context length. Peaks that happened before the long test (they don't grow with context) act as a floor; if a floor already exceeds the budget the model 'doesn't fit'. GGUF models in llama.cpp reserve their full context at load time, so for them the estimate is conservative.",
      see: ["ctx-peak", "reading-spike", "kv-cache", "context-window"] },
    { id: "reading-spike", term: "Reading spike (prefill working memory)", cat: "memory", aka: ["reading spike", "prefill spike"],
      short: "Extra memory used temporarily while a long prompt is being processed (intermediate results of the attention computation). It disappears once reading is done, but it sets the peak, so it decides how long a prompt a model can take on your machine.",
      see: ["prefill", "ctx-peak", "safe-context"] },
    { id: "system-used", term: "System memory used", cat: "memory", aka: ["system used", "system_used_bytes", "system used peak"],
      short: "All memory in use on the computer (apps, the operating system, compressed memory), not just the engine. Shows how close the whole machine got to its limit.",
      see: ["swap", "wired"] },
    { id: "wired", term: "Wired memory", cat: "memory", aka: ["wired", "wired_bytes"],
      short: "Memory macOS has locked in RAM (it can't be swapped out), e.g. buffers the GPU is using for model weights. Rises by roughly the model size when a GGUF model is loaded.",
      see: ["apple-silicon"] },
    { id: "swap", term: "Swap", cat: "memory", aka: ["swap", "swap δ", "swap_used_delta_bytes", "swap_growth_gb", "swap: speeds may be lower than usual"],
      short: "When RAM runs out, macOS moves memory to the SSD. Swapping during inference makes everything dramatically slower; a swap increase (Δ) during a run is a red flag. Above 1 GB of growth the run gets a warning: its speeds shouldn't be compared with clean runs.",
      see: ["mem-peak"] },
    { id: "memory-timeline", term: "Memory timeline / phases", cat: "memory", aka: ["memory timeline", "phase", "phases"],
      short: "Memory sampled every ~250 ms during the whole run, coloured by what was happening (load, warm-up, short, extraction, long…). Shows when memory jumps and whether it is released.",
      see: ["mem-engine"] },

    // ------------------------------------------------------------- tests & settings
    { id: "short-test", term: "Short test (multi-turn chat)", cat: "tests", aka: ["short", "short multi-turn conversation", "short test"],
      short: "A fixed 5-turn assistant conversation (explain, summarise, extract JSON, follow-up, plan) under 4k tokens. Represents everyday agent traffic from Hermes or n8n: lots of small requests.",
      see: ["ttft", "decode"] },
    { id: "extraction-test", term: "Extraction test (web data → JSON)", cat: "tests", aka: ["extraction", "web-data extraction", "extraction test", "extract acc."],
      short: "The model reads a saved model-card page and leaderboard snippet (~3k tokens) and must return the scores as JSON. Timed, and scored against a known answer key: a realistic structured-output task for automations.",
      see: ["extraction-accuracy", "json-valid", "live-extraction"] },
    { id: "long-test", term: "Long-context test (64k+)", cat: "tests", aka: ["long", "long (64k)", "long 64k", "long context", "long context (64k+ document)", "64k", "long test"],
      short: "The model receives a ~300k-character handbook (73–85k tokens depending on the tokenizer) and then answers questions about facts hidden at the start, middle and end. Measures prefill at scale, follow-up speed with a full context, and recall.",
      see: ["recall", "prefill", "followup-ttft", "kv-cache"] },
    { id: "recall", term: "Recall (hidden facts)", cat: "tests", aka: ["recall", "recall (64k)", "long_off_recall", "needle"],
      short: "How many of the 10 facts hidden in the long document the model found (a 'needle in a haystack' check). 100% = it really read everything; lower means it misses details in long inputs. The model page also shows recall per fact, grouped by the start, middle and end of the document.",
      see: ["long-test", "answer-in-reasoning"] },
    { id: "answer-in-reasoning", term: "Answer in the reasoning channel", cat: "tests", aka: ["answer in the reasoning channel", "answer(s) only in the reasoning channel", "answer_in_reasoning_channel", "recall in reasoning text", "accuracy of reasoning text"],
      short: "With thinking on, the model wrote its whole answer inside its thinking text and left the visible answer empty. Scores use the visible answer (what an agent receives), so they show 0; the 'in reasoning text' score shows what the model actually found.",
      see: ["recall", "reasoning-tokens"] },
    { id: "extraction-accuracy", term: "Extraction accuracy", cat: "tests", aka: ["accuracy", "extraction accuracy", "fields correct"],
      short: "Share of the 20 expected fields (model facts + benchmark scores) the model got exactly right in the extraction test. 0% usually means the output wasn't valid JSON or was cut off.",
      see: ["extraction-test", "json-valid", "truncated"] },
    { id: "json-valid", term: "JSON valid", cat: "tests", aka: ["json valid", "json_valid"],
      short: "Whether the model's answer contained a parseable JSON object. Important for automations that feed model output into the next step.",
      see: ["extraction-test"] },
    { id: "live-extraction", term: "Live extraction & agreement", cat: "tests", aka: ["live extraction", "live-extract", "agreement", "llm_extracted"],
      short: "Bonus step: the tested model reads the real web page about itself and extracts its benchmark scores. 'Agreement' = share of its values that match the tool's own table parser. No cloud AI is used.",
      see: ["extraction-test", "card-table"] },
    { id: "cold-cycles", term: "Cold cycles & warm-up", cat: "tests", aka: ["cold cycle", "cold cycles", "warmup", "warm-up", "cold start"],
      short: "Before the tests, the model is loaded twice from scratch (cold cycles) to time loading and the first request, then warmed up with a few short requests so the tests measure steady-state speed.",
      see: ["cold-load", "cold-ttft", "warm-ttft"] },
    { id: "repeats", term: "Repeats", cat: "tests", aka: ["repeats", "repeats / warmup"],
      short: "Each test is run 3 times (after one warm-up) and the median is reported, so a single slow moment doesn't distort the result.",
      see: ["median"] },
    { id: "session-tag", term: "Session tag (cache busting)", cat: "tests", aka: ["session tag", "cache busting"],
      short: "A unique label at the very start of each repeat's system prompt. It stops the engine from reusing the previous repeat's prompt cache, so prefill is genuinely measured every time.",
      see: ["prompt-cache"] },
    { id: "temperature", term: "Temperature, top_p, top_k, seed (sampling)", cat: "tests", aka: ["sampling", "temperature", "top_p", "top_k", "seed", "min_p", "repeat penalty"],
      short: "Settings controlling how 'random' the model's word choice is. The benchmark uses temperature 0 / top_k 1 (always the most likely token) and a fixed seed, so runs are as repeatable as possible.",
      see: ["profile"] },
    { id: "profile", term: "Profile (standard-v1) & profile hash", cat: "tests", aka: ["profile", "profile hash", "standard-v1", "profile_hash", "profile & machine"],
      short: "The fixed load and sampling settings every model is tested with (112k context, temperature 0, 3 repeats…), stored in config/profile.json. The hash changes if any setting changes, so old and new results are never mixed.",
      see: ["suite-version", "temperature"] },
    { id: "suite-version", term: "Suite version", cat: "tests", aka: ["suite version", "suite_version", "suite"],
      short: "Version of the fixed test content (prompts, document, answer keys). Bumped whenever a test changes, so results are only compared with results from the same tests.",
      see: ["profile"] },
    { id: "clean-machine", term: "Clean machine (unload & restore)", cat: "tests", aka: ["clean machine", "restore"],
      short: "Before testing, the tool unloads every model in LM Studio and Ollama so nothing else competes for memory or GPU, and reloads them when it's done (so your agents, e.g. Hermes, get their model back).",
      see: ["contamination", "load"] },
    { id: "contamination", term: "Contamination event", cat: "tests", aka: ["contamination", "contamination events", "contaminated"],
      short: "Another model got loaded during a test (e.g. Hermes or n8n asked for one). Within about 10 s the tool stops the test, unloads the other model and restarts the test; what the interrupted attempt measured is discarded. After 3 restarts it stops that model and names the culprit. Each event is recorded on the run.",
      see: ["clean-machine"] },
    { id: "truncated", term: "Truncated / hit the output limit", cat: "tests", aka: ["truncated", "truncated_turns", "hit the output limit"],
      short: "The model was still writing when it reached the maximum number of output tokens, so its answer was cut off. With thinking on this usually means it spent the whole thinking budget before answering.",
      see: ["thinking-budget", "no-answer-budget"] },
    { id: "no-answer-budget", term: "No answer: ran out of thinking budget", cat: "tests", aka: ["no answer", "never arrived", "ran out of thinking budget", "no_answer_budget_turns", "no_answer_thinking_budget"],
      short: "With thinking on, the model used the whole output budget on thinking and stopped before writing any visible answer. These count as wrong in recall and accuracy, so a low score with this label says the model thinks longer than the budget allows, not that its answers were wrong. Shown as “N of M answers never arrived” on the model page and “N/M no answer” in Compare.",
      see: ["thinking-budget", "truncated", "answer-in-reasoning"] },
    { id: "run-status", term: "Run status (complete / partial / failed)", cat: "tests", aka: ["status", "complete", "partial", "failed", "partial run", "no runs yet"],
      short: "Complete = all tests ran. Partial = interrupted or a quick/subset run (shown but not counted as 'benchmarked'). Failed = an error stopped it; ./bench run will retry it.",
      see: [] },
    { id: "machine", term: "Machine / platform", cat: "tests", aka: ["machine", "os", "cpu cores", "platform", "all machines"],
      short: "The computer the run happened on (model, chip, cores, RAM, operating system); Platform shows Mac, Win or Linux. Results from several computers can be combined with ./bench merge and shown together or filtered by machine.",
      see: ["apple-silicon"] },
    { id: "model-uid", term: "Model UID / fingerprint", cat: "tests", aka: ["model uid", "fingerprint", "run id", "key"],
      short: "The tool's identifiers: engine + model key + variant (e.g. lmstudio:google/gemma-4-26b-a4b-qat@4bit). The fingerprint changes if the file is re-downloaded or replaced.",
      see: ["variant"] },

    // ------------------------------------------------------------- thinking
    { id: "thinking-off", term: "Thinking off", cat: "thinking", aka: ["off", "reasoning off", "low"],
      short: "Thinking disabled, so the model answers right away. If a model can't disable thinking (Muse Glimmer, gpt-oss), its lowest level ('low') is used and recorded.",
      see: ["thinking-high", "reasoning-applied"] },
    { id: "thinking-high", term: "Thinking High", cat: "thinking", aka: ["high", "thinking high", "reasoning high", "on", "xhigh", "medium"],
      short: "Thinking at the 'High' level where the model offers it, otherwise the closest option ('on', then 'xhigh', then 'medium'). Shows the speed cost of thinking; quality gains are what the public benchmarks measure.",
      see: ["first-visible", "thinking-budget", "reasoning-applied"] },
    { id: "reasoning-applied", term: "Reasoning applied / observed", cat: "thinking", aka: ["reasoning applied", "reasoning_applied", "reasoning_observed", "applied"],
      short: "The thinking level the engine actually used for a test (models offer different levels). 'Observed' flags a model that still thought although thinking was set to off.",
      see: ["thinking-off", "thinking-high"] },
    { id: "reasoning-tokens", term: "Reasoning tokens", cat: "thinking", aka: ["reasoning tokens", "reasoning", "short_high_reasoning_tokens"],
      short: "Tokens the model spent thinking before its visible answer. They take decode time like any other token: 1,000 thinking tokens at 15 tok/s ≈ 67 s of waiting.",
      see: ["decode", "first-visible"] },
    { id: "reasoning-effort", term: "Reasoning effort (public scores)", cat: "thinking", aka: ["effort", "reasoning effort", "low effort", "high effort", "non-reasoning"],
      short: "Public evaluators often test a thinking model at several effort levels (e.g. gpt-oss at low and high). The tool keeps the lowest and the highest: the highest is the main score used in category scores and comparisons; the lowest is shown next to it. Your local tests run at 'off' (or the lowest level) and at High.",
      see: ["thinking-high", "thinking-off", "epoch"] },
    { id: "thinking-budget", term: "Thinking budget", cat: "thinking", aka: ["thinking budget", "reasoning_extra_tokens", "max tokens"],
      short: "Extra output tokens allowed per turn when thinking is on (3,072 short test, 8,192 extraction, 4,096 long). If a model thinks longer than that, its answer gets cut off (truncated).",
      see: ["truncated"] },

    // ------------------------------------------------------------- public data
    { id: "public-benchmarks", term: "Public benchmarks", cat: "public", aka: ["public scores", "public benchmarks", "intelligence", "intelligence (public benchmarks)", "all benchmarks"],
      short: "Scores published by model makers and independent evaluators on standard tests (reasoning, coding, agents…). They measure how capable a model is, which this tool can't measure locally. Collected with source links.",
      long: "Treat them as indicative: vendors choose their settings, scores often come from the full-precision model with thinking on, and sources don't always agree. Compare like with like (same benchmark, same source) when you can.",
      see: ["categories", "applies-to", "method"] },
    { id: "categories", term: "Benchmark categories", cat: "public", aka: ["by category", "category", "knowledge", "math", "coding", "agentic", "instruction following", "long_context", "instruction_following", "other"],
      short: "Benchmarks are grouped into reasoning, knowledge, math, coding, agentic (tool use, multi-step tasks), vision, long context and instruction following. Category scores are the average of the 0–100 scores in that group.",
      see: ["public-benchmarks", "fit-score"] },
    { id: "applies-to", term: "Applies to: base vs exact", cat: "public", aka: ["applies to", "applies_to", "exact"],
      short: "'base' = the score was measured on the original model (usually full precision), not on your quantized file. 'exact' = measured on this exact file. Expect your 4-bit copy to be slightly lower than 'base' scores (less so with QAT).",
      see: ["base-model", "qat"] },
    { id: "method", term: "Method (where a score came from)", cat: "public", aka: ["method", "source", "card-table", "leaderboard", "model-index", "manual", "card-link", "web"],
      short: "card-table = the model card's benchmark table; leaderboard = Epoch AI's dataset; api = Artificial Analysis; card-link/web = linked pages; local-llm = extracted by the tested model; manual = your overrides (always win).",
      see: ["card-table", "epoch"] },
    { id: "card-table", term: "card-table", cat: "public", aka: [],
      short: "Score read from a benchmark table on the model's Hugging Face card, using the column for this exact model size.",
      see: ["model-card", "method"] },
    { id: "epoch", term: "Epoch AI Benchmarking Hub", cat: "public", aka: ["epoch ai", "epoch.ai"],
      short: "An independent research group that runs and publishes benchmark results for many models (free, CC-BY). Used as a second source; when it ran a model at several reasoning efforts, both the lowest and the highest are kept.",
      see: ["method"] },
    { id: "artificial-analysis", term: "Artificial Analysis", cat: "public", aka: ["artificial analysis"],
      short: "An independent benchmarking company with indexes for intelligence, coding and agents. Used only if you add their free API key.",
      see: ["method"] },

    // ------------------------------------------------------------- named benchmarks
    { id: "mmlu-pro", term: "MMLU-Pro", cat: "bench", aka: ["mmlu-pro", "mmlu pro"],
      short: "Knowledge & reasoning: ~12,000 multiple-choice questions (10 options) across 14 subjects such as law, engineering and biology. A harder version of the classic MMLU.",
      see: ["categories"] },
    { id: "mmmlu", term: "MMMLU", cat: "bench", aka: ["mmmlu"],
      short: "Multilingual MMLU: the MMLU knowledge test translated into many languages. Shows how well a model works outside English.",
      see: ["mmlu-pro"] },
    { id: "gpqa", term: "GPQA Diamond", cat: "bench", aka: ["gpqa diamond", "gpqa"],
      short: "Reasoning: 198 very hard graduate-level science multiple-choice questions written so they can't be answered by searching. Random guessing scores 25%; PhD experts in the field score around 65–80%.",
      see: ["categories"] },
    { id: "hle", term: "HLE (Humanity's Last Exam)", cat: "bench", aka: ["hle"],
      short: "Reasoning: ~2,500 expert-level questions across many fields, designed to be at the frontier of human knowledge. Scores are low (often under 30%) even for top models.",
      see: [] },
    { id: "bbeh", term: "BIG-Bench Extra Hard", cat: "bench", aka: ["bigbench extra hard", "big-bench extra hard", "bbeh"],
      short: "Reasoning: a set of very hard logic, planning and puzzle tasks (successor of BIG-Bench Hard).",
      see: [] },
    { id: "aime", term: "AIME (2024 / 2025 / 2026)", cat: "bench", aka: ["aime 2026", "aime 2025", "aime 2024", "aime", "otis mock aime"],
      short: "Math: problems from the American Invitational Mathematics Examination, a hard high-school competition (answers are whole numbers). Strongly favours models with thinking.",
      see: [] },
    { id: "livecodebench", term: "LiveCodeBench", cat: "bench", aka: ["livecodebench"],
      short: "Coding: competitive-programming problems collected continuously after models' training cut-off, so models can't have memorised them.",
      see: ["codeforces"] },
    { id: "codeforces", term: "Codeforces Elo", cat: "bench", aka: ["codeforces", "codeforces elo"],
      short: "Coding: a rating on the Codeforces competitive-programming scale (like chess Elo, not a percentage). ~1,500 is a decent human contestant, 2,100+ is expert level.",
      see: ["livecodebench"] },
    { id: "swe-bench", term: "SWE-bench (Verified / Pro)", cat: "bench", aka: ["swe-bench verified", "swe-bench pro", "swe-bench", "swe-bench multilingual"],
      short: "Agentic coding: real GitHub issues from open-source projects; the model must change the code so the project's tests pass. Verified = 500 human-checked Python tasks; Pro = harder, longer tasks.",
      see: ["terminal-bench"] },
    { id: "terminal-bench", term: "Terminal-Bench", cat: "bench", aka: ["terminal-bench", "terminal bench"],
      short: "Agentic: tasks solved by running commands in a real terminal (installing, configuring, debugging). Close to what coding agents do on a computer.",
      see: ["swe-bench"] },
    { id: "tau2", term: "τ²-bench / τ³-bench (tau-bench)", cat: "bench", aka: ["τ²-bench", "τ³-bench", "tau2", "tau-bench", "τ-bench"],
      short: "Agentic tool use: the model acts as a customer-service agent (airline, retail, telecom…) that must use tools and follow company policy while talking to a simulated customer. Very relevant for Hermes-style assistants.",
      see: ["tool-use", "bfcl"] },
    { id: "bfcl", term: "BFCL (Berkeley Function Calling Leaderboard)", cat: "bench", aka: ["bfcl", "bfcl v3"],
      short: "Agentic: how accurately a model calls functions/tools (right function, right arguments, knowing when not to call). Directly relevant for n8n tool nodes and MCP.",
      see: ["tool-use", "tau2"] },
    { id: "mcp-atlas", term: "MCP Atlas", cat: "bench", aka: ["mcp atlas"],
      short: "Agentic: multi-step tasks using real tools exposed through MCP servers (the Model Context Protocol).",
      see: ["tool-use"] },
    { id: "osworld", term: "OSWorld", cat: "bench", aka: ["osworld"],
      short: "Agentic computer use: the model operates real desktop apps (via screenshots and clicks) to complete tasks.",
      see: [] },
    { id: "gaia", term: "GAIA", cat: "bench", aka: ["gaia"],
      short: "Agentic: real-world assistant questions that need web browsing, tools and several steps to answer.",
      see: [] },
    { id: "ifeval", term: "IFEval / IFBench", cat: "bench", aka: ["ifeval", "ifbench"],
      short: "Instruction following: prompts with checkable rules ('answer in 3 bullet points', 'no commas', 'end with a question'). High scores mean the model sticks to formatting instructions, which matters for automations.",
      see: [] },
    { id: "mmmu", term: "MMMU / MMMU-Pro", cat: "bench", aka: ["mmmu", "mmmu pro"],
      short: "Vision: college-level questions that combine text with images (charts, diagrams, tables) across many subjects.",
      see: ["vision"] },
    { id: "math-vision", term: "MATH-Vision", cat: "bench", aka: ["math-vision"],
      short: "Vision + math: competition math problems where the key information is in a figure.",
      see: [] },
    { id: "omnidocbench", term: "OmniDocBench", cat: "bench", aka: ["omnidocbench"],
      short: "Vision: turning document pages (PDF scans) into structured text. Careful: some vendors report an edit distance (lower is better, e.g. 0.13) and others a 0–100 score.",
      see: [] },
    { id: "screenspot", term: "ScreenSpot Pro / CharXiv", cat: "bench", aka: ["screenspot pro", "charxiv"],
      short: "Vision: ScreenSpot Pro = finding the right button or element in high-resolution app screenshots (for computer-use agents). CharXiv = understanding charts from scientific papers.",
      see: [] },
    { id: "mrcr", term: "MRCR / RULER / AA-LCR", cat: "bench", aka: ["mrcr", "ruler", "aa-lcr", "beam128k", "longbench"],
      short: "Long context: tests whether a model can find and combine information spread across very long inputs (e.g. 128k tokens). Public counterpart to this tool's recall check.",
      see: ["recall", "long-test"] },
    { id: "simpleqa", term: "SimpleQA", cat: "bench", aka: ["simpleqa"],
      short: "Knowledge: short factual questions. Low scores mean the model often doesn't know or makes things up (hallucination); small local models score low here.",
      see: [] },
    { id: "arena", term: "Arena Elo (LMArena)", cat: "bench", aka: ["arena elo", "lmarena"],
      short: "Human preference: people compare two anonymous answers and vote; votes become an Elo rating. Reflects how pleasant and helpful answers feel, not correctness on hard tasks.",
      see: [] },

    // ------------------------------------------------------------- dashboard
    { id: "fit-score", term: "Fit score", cat: "dashboard", aka: ["fit", "fit score", "best fit"],
      short: "A 0–100 score combining the metrics you care about, weighted by the sliders (speed, long context, intelligence, agentic, memory). Each metric is scaled between the worst and best model shown, so it ranks the models you have; it's not an absolute grade.",
      long: "Because scores are relative to the models on screen, adding a much faster or smarter model changes everyone's score. Use it to shortlist, then check the details.",
      see: ["fit-speed", "fit-long", "fit-intel", "fit-agentic", "fit-memory"] },
    { id: "fit-speed", term: "Fit: Speed", cat: "dashboard", aka: ["fit: speed"],
      short: "Slider weight for everyday responsiveness: short-test decode speed and time to first token. Raise it for chatty assistants and many small automation calls.",
      see: ["fit-score", "short-test"] },
    { id: "fit-long", term: "Fit: Long context", cat: "dashboard", aka: ["fit: long context"],
      short: "Slider weight for working with big inputs: 64k prefill speed, TTFT, decode and recall. Raise it for document summarising, RAG and agents with large tool lists or history.",
      see: ["fit-score", "long-test"] },
    { id: "fit-intel", term: "Fit: Intelligence", cat: "dashboard", aka: ["fit: intelligence"],
      short: "Slider weight for public reasoning, coding, math and knowledge scores.",
      see: ["fit-score", "public-benchmarks"] },
    { id: "fit-agentic", term: "Fit: Agentic", cat: "dashboard", aka: ["fit: agentic"],
      short: "Slider weight for public agentic/tool-use scores plus this tool's extraction accuracy. Raise it for Hermes, n8n agents and anything that calls tools.",
      see: ["fit-score", "tau2", "bfcl", "extraction-test"] },
    { id: "fit-memory", term: "Fit: Memory efficiency", cat: "dashboard", aka: ["fit: memory efficiency", "memory efficiency"],
      short: "Slider weight for lower peak memory. Raise it if you want to keep several models loaded at once or leave room for other apps.",
      see: ["fit-score", "mem-peak"] },
    { id: "compare", term: "Compare", cat: "dashboard", aka: ["compare", "key metrics"],
      short: "Tick up to 3 models in the table and press Compare to see them side by side; the best value in each row is highlighted.",
      see: [] },
    { id: "run", term: "Run / run history", cat: "dashboard", aka: ["run history", "run & engine", "run"],
      short: "One complete benchmark of one model on one machine. Re-testing a model (./bench run --force) adds a new run; older runs stay in the history.",
      see: ["run-status"] },
  ];

  // ---------------------------------------------------------------- lookup tables
  const byId = new Map();
  const exact = new Map();
  const patterns = [];
  const norm = (s) => String(s || "").toLowerCase().replace(/\s+/g, " ").replace(/[:·]+$/, "").trim();
  for (const g of BL.GLOSSARY) {
    byId.set(g.id, g);
    for (const a of [g.term].concat(g.aka || [])) {
      if (a.length > 2 && a[0] === "/" && a[a.length - 1] === "/") patterns.push([new RegExp(a.slice(1, -1), "i"), g.id]);
      else if (!exact.has(norm(a))) exact.set(norm(a), g.id);
    }
  }
  BL.glossaryById = (id) => byId.get(id);
  BL.glossaryLookup = (label) => {
    const n = norm(label);
    if (!n || n.length > 60) return null;
    const tries = [n,
      n.replace(/\s*\([^)]*\)\s*$/, ""),                       // "Decode (off)" -> "decode"
      n.replace(/^(high|off|thinking high|reasoning off)\s*[:·]\s*/, ""), // "High: first visible token"
      n.replace(/\s*[·,].*$/, "")];                                // "4bit · QAT" -> "4bit"
    for (const t of tries) if (t && exact.has(t)) return exact.get(t);
    for (const t of tries) for (const [re, id] of patterns) if (t && re.test(t)) return id;
    return null;
  };
  // Inline helper for hand-written HTML: BL.t("ttft") or BL.t("ttft", "time to first token")
  BL.t = (id, label) => {
    const g = byId.get(id);
    return '<span class="term" data-term="' + id + '" tabindex="0">' + BL.esc(label || (g ? g.term : id)) + "</span>";
  };
})();
